using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CityMobileDetailAudit{static CityMobileDetailAudit(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CityMobileDetailAudit.request"))return;File.Delete("CityMobileDetailAudit.request");try{var sc=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var rs=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).ToArray();var s=new StringBuilder();foreach(var g in rs.Where(r=>r.GetComponent<MeshFilter>()&&!r.GetComponentInParent<LODGroup>()).GroupBy(r=>r.GetComponent<MeshFilter>().sharedMesh).Where(g=>g.Key).OrderByDescending(g=>g.Count()*(long)g.Key.GetIndexCount(0)).Take(35)){var r=g.First();s.AppendLine("MESH "+g.Key.name+" count="+g.Count()+" tri="+g.Key.GetIndexCount(0)/3+" size="+r.bounds.size+" components="+string.Join(",",r.GetComponents<Component>().Select(c=>c.GetType().Name))+" children="+r.transform.childCount+" source="+PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(r.gameObject));}foreach(var r in rs.Where(r=>r.name.StartsWith("GardenPlants_")||r.name.StartsWith("PortalIvy_")||r.name.StartsWith("Fountain_poly")).Take(25))s.AppendLine("GARDEN "+r.name+" isPrefab="+PrefabUtility.IsPartOfPrefabInstance(r)+" outer="+PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(r.gameObject)+" parent="+r.transform.parent.name+" children="+r.transform.childCount);var tex=rs.SelectMany(r=>r.sharedMaterials).Where(m=>m).Distinct().SelectMany(m=>m.GetTexturePropertyNames().Select(n=>m.GetTexture(n))).OfType<Texture2D>().Distinct();foreach(var t in tex){var path=AssetDatabase.GetAssetPath(t);var imp=AssetImporter.GetAtPath(path) as TextureImporter;if(imp==null)continue;var a=imp.GetPlatformTextureSettings("Android");s.AppendLine("TEXTURE "+path+" size="+t.width+"x"+t.height+" readable="+imp.isReadable+" mips="+imp.mipmapEnabled+" stream="+imp.streamingMipmaps+" android="+a.overridden+" format="+a.format+" max="+a.maxTextureSize);}File.WriteAllText("FinalEnvironmentRoadReview/MobileDetailAudit.txt",s.ToString());}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/MobileDetailAudit.txt",e.ToString());}}}
